<script setup lang="ts">
import {clientFetch,isInstalledClient} from '../client';

import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {auth,bootstrapAuth,clearAuth,switchEdition} from '../auth/bootstrap';import {responseError} from '../http';import {useBusinessStore,businessApi} from '../stores/business';import {useSessionStore} from '../stores/session';import {useRunStore} from '../stores/run';import {useEvidenceUpload} from '../stores/evidence-upload';import {useConversationController} from '../composables/useConversationController';import {useVisibleRefresh} from '../composables/useVisibleRefresh';
import {useMobileNavigation} from './navigation';import {useMobileViewport} from './viewport';import type {Notice} from '@shared/mobile';
import {useSwipeBack,useDragClose,usePullToRefresh} from './gestures';
import {useModal} from '../composables/useModal';
import {t as tr} from '../i18n';import UiIcon from '../components/UiIcon.vue';import MobileStart from './MobileStart.vue';
import ToastHost from '../components/ToastHost.vue';import ConfirmSheet from '../components/ConfirmSheet.vue';
import {defineAsyncComponent} from 'vue';
const SettingsPanel=defineAsyncComponent(()=>import('../components/SettingsPanel.vue'));
const MobileHome=defineAsyncComponent(()=>import('./MobileHome.vue'));
const MobileSessions=defineAsyncComponent(()=>import('./MobileSessions.vue'));
const MobileConversation=defineAsyncComponent(()=>import('./MobileConversation.vue'));
const MobileRooms=defineAsyncComponent(()=>import('./MobileRooms.vue'));
const MobileMessages=defineAsyncComponent(()=>import('./MobileMessages.vue'));
const MobileProfile=defineAsyncComponent(()=>import('./MobileProfile.vue'));
const MobileTask=defineAsyncComponent(()=>import('./MobileTask.vue'));
const ScheduledJobsPanel=defineAsyncComponent(()=>import('../components/ScheduledJobsPanel.vue'));
const EvidencePanel=defineAsyncComponent(()=>import('../components/EvidencePanel.vue'));
const business=useBusinessStore(),session=useSessionStore(),run=useRunStore(),upload=useEvidenceUpload(),navigation=useMobileNavigation(auth.target.value),{route,sheet,error:routeError}=navigation,{keyboard}=useMobileViewport(),authed=auth.authenticated,loading=ref(true),error=ref(auth.error.value),account=ref(''),password=ref(''),loggingIn=ref(false),unread=ref<number|null>(null),content=ref<HTMLElement>(),offline=ref(!navigator.onLine);
// 安装版登录页只保留一个低调的「连接设置」文字入口（原「应用设置」悬浮按钮已取消）。
const installed=isInstalledClient();
function openAdvanced(){location.assign('/client/settings.html#advanced');}
const accountSheet=computed({get:()=>sheet.value==='account',set:value=>{if(!value)navigation.closeSheet();}});useModal(accountSheet,'.mobile-sheet');
const controller=useConversationController(id=>navigation.go({view:'conversation',conversationId:id},route.value.view==='conversation'));
const title=computed(()=>({home:'工作台',assistant:'助手',sessions:'历史会话',settings:'设置',conversation:'会话',rooms:'实验室',room:'实验室详情',automation:'自动化',job:'规则详情',task:'正式任务',messages:'消息中心',notice:'通知详情',profile:'我的',evidence:'证据与资料'} as Record<string,string>)[route.value.view]||'LabOps');
const activeTab=computed(()=>['conversation','assistant','sessions'].includes(route.value.view)?'assistant':['rooms','room','task'].includes(route.value.view)?'rooms':['profile','settings','automation','job','evidence','messages','notice'].includes(route.value.view)?'profile':'home');
if(authed.value&&auth.error.value)routeError.value=auth.error.value;
const tabs=[{view:'assistant',label:'助手',icon:'chat'},{view:'rooms',label:'实验室',icon:'room'},{view:'home',label:'工作台',icon:'work'},{view:'profile',label:'我的',icon:'more'}];
// 批次 B：视图切换动效 —— 按视图等级判定 推入(m-push)/退回(m-pop)/淡切(m-fade)，方案 4.2
const viewRank:Record<string,number>={assistant:0,rooms:0,home:0,profile:0,sessions:1,conversation:1,settings:1,automation:1,messages:1,task:2,evidence:2,room:2,job:3,notice:3};
const transitionName=ref('m-fade');
watch(()=>route.value,(next,previous)=>{if(!previous)return transitionName.value='m-fade';const from=viewRank[previous.view]??1,to=viewRank[next.view]??1;transitionName.value=to>from?'m-push':to<from?'m-pop':'m-fade';});
const viewKey=computed(()=>[route.value.view,route.value.conversationId||'',route.value.roomId||'',route.value.taskId||'',route.value.jobId||'',route.value.noticeId||'',route.value.section||'',route.value.action||''].join('|'));
// 批次 C：手势层 —— 边缘右滑返回 / 顶部下拉刷新 / 账户弹层拖拽关闭（方案 4.3）
useSwipeBack(()=>content.value??null,()=>!['home','assistant','rooms','profile'].includes(route.value.view)&&!sheet.value,()=>navigation.back());
const ptr=usePullToRefresh(()=>content.value??null,()=>['home','rooms','messages'].includes(route.value.view),()=>route.value.view);
const acctDrag=useDragClose(()=>navigation.closeSheet());
function newChat(){if(run.inputLocked||controller.submitting.value)return;session.startDraft();navigation.go({view:'assistant'});}
async function notices(){if(!business.connected)return;try{const result=await businessApi<{notifications:Notice[]}>('proxy/notifications?limit=100');unread.value=result.notifications.filter(n=>!n.readAt).length;}catch{unread.value=null;}}
async function workspace(){loading.value=true;try{await business.refresh();if(!business.connected)throw new Error(business.error||'主系统业务接口暂不可用，恢复后重新读取');await session.loadConversations();await notices();error.value='';}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
onMounted(async()=>{if(authed.value)await workspace();else loading.value=false;});
async function login(){if(loggingIn.value||!account.value.trim()||!password.value)return;loggingIn.value=true;error.value='';try{if(auth.mode.value==='native'){const res=await clientFetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account:account.value.trim(),password:password.value})});if(!res.ok)throw await responseError(res);}sessionStorage.removeItem('labops.manual-logout');sessionStorage.setItem('labops.auth',account.value.trim());password.value='';await bootstrapAuth(true);if(!authed.value)throw new Error(auth.error.value||'身份验证失败');await workspace();navigation.go(auth.target.value,true);}catch(e){error.value=(e as Error).message;}finally{loggingIn.value=false;}}
function clearDrafts(){for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(key?.startsWith('labops.native-draft:'))localStorage.removeItem(key);}}
async function logout(){sessionStorage.setItem('labops.manual-logout','1');controller.dispose();session.clearPrivate();upload.clearPrivate();business.clearPrivate();clearDrafts();clearAuth();unread.value=null;navigation.go({view:'home'},true);try{const response=await clientFetch('/api/auth/logout',{method:'POST'});if(!response.ok)throw await responseError(response);error.value='';}catch(e){error.value='已清空本机工作区，服务端退出尚未确认：'+(e as Error).message;}}
useVisibleRefresh(notices,()=>authed.value&&!run.inputLocked);
const scrolls=new Map<string,number>();watch(route,async(next,previous)=>{if(previous)scrolls.set(JSON.stringify(previous),content.value?.scrollTop||0);auth.target.value=next;await nextTick();if(content.value)content.value.scrollTop=scrolls.get(JSON.stringify(next))||0;});
watch(()=>business.scopeKey,(next,previous)=>{if(previous&&next!==previous){controller.dispose();session.clearPrivate();upload.clearPrivate();unread.value=null;scrolls.clear();}});
const connectivity=()=>offline.value=!navigator.onLine;window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);onUnmounted(()=>{window.removeEventListener('online',connectivity);window.removeEventListener('offline',connectivity);controller.dispose();});
</script>
<template><div class="mobile-shell" :class="{'mobile-keyboard':keyboard}"><template v-if="!authed"><main class="mobile-login"><div class="mobile-brand"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3h8 M9 3v6L4 19q0 2 2 2h12q2 0 2-2l-5-10V3 M8 14h8"/></svg><b>LabOps</b><span>{{tr("实验室工作助手")}}</span></div><h1>{{tr("使用主系统账号登录")}}</h1><p>{{tr("管理员与志愿者身份由主系统识别。")}}</p><form class="mobile-form" @submit.prevent="login"><label for="mobile-account">{{tr("账号")}}<input id="mobile-account" v-model="account" autocomplete="username" required maxlength="100"></label><label for="mobile-password">{{tr("密码")}}<input id="mobile-password" v-model="password" type="password" autocomplete="current-password" required maxlength="200"></label><p v-if="error" role="alert">{{error}}</p><button class="mobile-primary" :disabled="loggingIn">{{tr(loggingIn?'正在验证…':'登录')}}</button></form><p>{{tr("学生请使用主系统中的共享聊天入口。")}}</p><button v-if="installed" type="button" class="mobile-conn-link" @click="openAdvanced">{{tr("连接设置")}}</button></main></template><template v-else><header class="mobile-header"><button v-if="!['home','assistant','rooms','profile'].includes(route.view)" :aria-label="tr('返回')" @click="navigation.back"><UiIcon name="chevron" class="mobile-back-icon"/></button><div><b>{{tr(title)}}</b><small v-if="!['assistant','conversation','sessions'].includes(route.view)">{{business.profile?.username||auth.profile.value?.username}}</small></div><template v-if="['assistant','conversation','sessions'].includes(route.view)"><button :aria-label="tr('历史会话')" @click="navigation.go({view:'sessions',section:session.currentMode()==='chat'?'chat':'work'})"><UiIcon name="history"/></button><button class="mobile-header-new" :aria-label="tr('新建会话')" :disabled="run.inputLocked||controller.submitting.value" @click="newChat"><UiIcon name="new"/><span>{{tr('新会话')}}</span></button></template><button :aria-label="tr('账户菜单')" @click="navigation.openSheet('account')"><UiIcon name="user"/></button></header><div v-if="ptr.progress.value>0||ptr.refreshing.value" class="m-ptr" :class="{'is-armed':ptr.armed.value,'is-refreshing':ptr.refreshing.value}" :style="{height:Math.round((ptr.refreshing.value?1:Math.min(1,ptr.progress.value))*36)+'px'}" role="status"><span aria-hidden="true">↻</span>{{tr(ptr.refreshing.value?'正在刷新…':ptr.armed.value?'松手刷新':'下拉刷新')}}</div><p v-if="offline" class="mobile-offline" role="status">{{tr("网络未连接，输入保留。恢复后按原会话或方案编号回查。")}}</p><main ref="content" v-on="ptr.handlers" class="mobile-content" :class="{'mobile-content-conversation':['conversation','assistant'].includes(route.view)}"><p v-if="routeError" role="alert">{{routeError}}</p><p v-if="loading" class="mobile-state" role="status">{{tr("正在恢复本人工作区…")}}</p><div v-else-if="error" class="mobile-state" role="alert"><p>{{error}}</p><button @click="workspace">{{tr("重新读取")}}</button><button @click="logout">{{tr("退出登录")}}</button></div><Transition :name="transitionName" mode="out-in"><div v-if="!loading&&!error&&business.connected" :key="viewKey" class="mobile-view"><MobileHome v-if="route.view==='home'" :key="business.scopeKey" @navigate="navigation.go"/><MobileStart v-else-if="route.view==='assistant'" :controller="controller" :section="route.section" @navigate="navigation.go"/><MobileSessions v-else-if="route.view==='sessions'" :section="route.section" @navigate="navigation.go"/><MobileConversation v-else-if="route.view==='conversation'&&route.conversationId" :conversation-id="route.conversationId" :controller="controller"/><MobileRooms v-else-if="route.view==='rooms'||route.view==='room'" :room-id="route.roomId" :action="route.action" @navigate="navigation.go"/><ScheduledJobsPanel v-else-if="route.view==='automation'||route.view==='job'" :inline="true" :job-id="route.jobId" :readonly="run.inputLocked" @navigate="navigation.go"/><MobileTask v-else-if="route.view==='task'&&route.taskId" :task-id="route.taskId"/><MobileMessages v-else-if="route.view==='messages'||route.view==='notice'" :notice-id="route.noticeId" @navigate="navigation.go" @changed="notices"/><SettingsPanel v-else-if="route.view==='settings'" :category="route.category" @edition="switchEdition('desktop',session.currentId?{view:'conversation',conversationId:session.currentId}:route)" @logout="logout"/><MobileProfile v-else-if="route.view==='profile'" @logout="logout" @navigate="navigation.go"/><EvidencePanel v-else-if="route.view==='evidence'" :inline="true" :room-id="route.roomId" :issue-id="route.issueId" :readonly="run.inputLocked"/></div></Transition></main><button v-if="run.inputLocked&&route.view!=='conversation'&&controller.activeConversation.value" class="mobile-run-banner" @click="navigation.go({view:'conversation',conversationId:controller.activeConversation.value})">{{tr("本人的会话仍在生成 · 返回查看")}}</button><nav v-show="!keyboard" class="mobile-bottom-nav" :aria-label="tr('主要导航')"><button v-for="tab in tabs" :key="tab.view" :aria-current="activeTab===tab.view?'page':undefined" @click="navigation.go({view:tab.view})"><UiIcon :name="tab.icon"/><span>{{tr(tab.label)}}</span></button></nav><div v-if="sheet" class="mobile-sheet-mask" @click.self="navigation.closeSheet"><section class="mobile-sheet" role="dialog" aria-modal="true" v-on="acctDrag.handlers" :style="acctDrag.style.value"><h2>{{tr("本人账户")}}</h2><p>{{business.profile?.username}} · {{tr(business.profile?.identity==='admin'?'管理员':'志愿者')}}</p><button @click="navigation.go({view:'settings'})">{{tr('设置')}}</button><button @click="navigation.go({view:'profile'})">{{tr('更多')}}</button><button @click="navigation.closeSheet">{{tr("关闭账户菜单")}}</button><button class="mobile-danger" @click="logout">{{tr("退出登录")}}</button></section></div></template><ToastHost/><ConfirmSheet/></div></template>
